CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('FARMER','CONSUMER','BULK_BUYER','FPO_ADMIN','ADMIN')), created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS farmers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id), farm_name TEXT NOT NULL, village TEXT NOT NULL, district TEXT NOT NULL, state TEXT NOT NULL, location GEOGRAPHY(Point,4326), fpo_id UUID, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS fpos (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, location GEOGRAPHY(Point,4326), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS buyers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id), business_name TEXT NOT NULL, location GEOGRAPHY(Point,4326), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS consumers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id), address TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS crops (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT UNIQUE NOT NULL, unit TEXT NOT NULL DEFAULT 'kg');
CREATE TABLE IF NOT EXISTS crop_listings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farmer_id UUID REFERENCES farmers(id), crop_id UUID REFERENCES crops(id), quantity NUMERIC NOT NULL CHECK(quantity > 0), unit TEXT NOT NULL, quality TEXT NOT NULL, price NUMERIC NOT NULL CHECK(price >= 0), harvest_date DATE, status TEXT NOT NULL DEFAULT 'ACTIVE', source TEXT NOT NULL DEFAULT 'WEB' CHECK (source IN ('WEB','VOICE','USSD','IVR')), created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), buyer_id UUID, consumer_id UUID, status TEXT NOT NULL DEFAULT 'PENDING', total NUMERIC NOT NULL, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID REFERENCES orders(id), listing_id UUID REFERENCES crop_listings(id), quantity NUMERIC NOT NULL, price NUMERIC NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID REFERENCES orders(id), amount NUMERIC NOT NULL, status TEXT NOT NULL, simulated BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_splits (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payment_id UUID REFERENCES payments(id), recipient_type TEXT NOT NULL, amount NUMERIC NOT NULL);
CREATE TABLE IF NOT EXISTS transporters (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vehicles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transporter_id UUID REFERENCES transporters(id), capacity NUMERIC NOT NULL, location GEOGRAPHY(Point,4326));
CREATE TABLE IF NOT EXISTS routes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id UUID REFERENCES vehicles(id), distance NUMERIC, estimated_cost NUMERIC, status TEXT DEFAULT 'PLANNED');
CREATE TABLE IF NOT EXISTS route_stops (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), route_id UUID REFERENCES routes(id), stop_order INT NOT NULL, label TEXT NOT NULL, location GEOGRAPHY(Point,4326));
CREATE TABLE IF NOT EXISTS pickup_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID REFERENCES orders(id), farmer_id UUID REFERENCES farmers(id), fpo_id UUID REFERENCES fpos(id), crop_id UUID REFERENCES crops(id), quantity NUMERIC NOT NULL CHECK(quantity > 0), pickup_latitude NUMERIC, pickup_longitude NUMERIC, pickup_address TEXT NOT NULL, preferred_date DATE NOT NULL, preferred_time TIME NOT NULL, special_instructions TEXT, status TEXT NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED','FPO_ACCEPTED','VEHICLE_ASSIGNED','PICKUP_SCHEDULED','PICKED_UP','IN_TRANSIT','DELIVERED','CANCELLED')), vehicle_id UUID REFERENCES vehicles(id), transporter_id UUID REFERENCES transporters(id), route_id UUID REFERENCES routes(id), created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS price_predictions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), listing_id UUID REFERENCES crop_listings(id), reference_price NUMERIC, predicted_price NUMERIC, confidence NUMERIC, factors JSONB, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS demand_forecasts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crop_id UUID REFERENCES crops(id), forecast_date DATE, predicted_demand NUMERIC, available_supply NUMERIC);
CREATE TABLE IF NOT EXISTS ledger_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID REFERENCES orders(id), transaction_code TEXT UNIQUE NOT NULL, amount NUMERIC NOT NULL, hash TEXT NOT NULL, status TEXT NOT NULL, simulated BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID, message TEXT NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS listings_status_idx ON crop_listings(status); CREATE INDEX IF NOT EXISTS orders_status_idx ON orders(status); CREATE INDEX IF NOT EXISTS routes_status_idx ON routes(status); CREATE INDEX IF NOT EXISTS pickup_requests_status_idx ON pickup_requests(status); CREATE INDEX IF NOT EXISTS pickup_requests_order_idx ON pickup_requests(order_id);
